"use strict";(self.webpackChunknomos_docusaurus_template=self.webpackChunknomos_docusaurus_template||[]).push([[6306],{79347:e=>{e.exports=JSON.parse('{"version":{"pluginId":"about","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","label":"Vision","href":"/about/","docId":"index","unlisted":false},{"type":"link","label":"Description and Architecture","href":"/about/architect","docId":"architect","unlisted":false},{"type":"link","label":"Development Roadmap","href":"/about/roadmap","docId":"roadmap","unlisted":false},{"type":"link","label":"Core Contributors","href":"/about/team","docId":"team","unlisted":false}]},"docs":{"architect":{"id":"architect","title":"Description and Architecture","description":"Nomos is a blockchain infrastructure that makes it easy to build network states and other decentralised applications. It was designed with the following principles in mind:","sidebar":"defaultSidebar"},"index":{"id":"index","title":"Vision","description":"Once again, the world stands at a crossroads. For as long as humanity has lived together, there have been individuals seeking to control others, and individuals seeking freedom from that control. As history marched onward, technologies emerged that shifted this struggle toward one side or the other. From writing, to gunpowder, to the printing press, to the revolver \u2013 inventions would periodically arise and upset the balance of forces in unpredictable ways. In recent times, the internet \u2013 initially hailed as a bastion for free speech and free association \u2013 has become a tool for mass surveillance and control.","sidebar":"defaultSidebar"},"roadmap":{"id":"roadmap","title":"Development Roadmap","description":"At the time of writing, the Nomos team is preparing to launch its public testnet in early 2026. With the majority of its protocols and architecture specified, the focus of effort is now placed on implementing Nomos V1. At the same time, research remains ongoing for improvements to the project, providing a vision for future iterations of Nomos.","sidebar":"defaultSidebar"},"team":{"id":"team","title":"Core Contributors","description":"Nomos is being built by a team of passionate and experienced blockchain developers and researchers. Alongside Nomos\' project lead is a team of researchers and developers with experience as software engineers both within and beyond the blockchain and cypherpunk ecosystem, as well as in academia.","sidebar":"defaultSidebar"}}}}')}}]);